19	// failureIn builds a remembered failure the way the registry would hand it out.
20	func failureIn(contextName, target string, seq uint64) jobs.Failure {
21		return jobs.Failure{
22			FailureKey: jobs.FailureKey{Kind: jobs.KindScan, Target: target, Context: contextName},
23			Display:    target,
24			Detail:     "boom",
25			Seq:        seq,
26		}
27	}
28	
29	func withFailures(t *testing.T, runs []jobs.Run, failures ...jobs.Failure) Model {
30		t.Helper()
31		return feed(t, newModel(t), jobs.ChangedMsg{Runs: runs, Failures: failures, Context: testContext})
32	}
33	
34	func headerValue(t *testing.T, m Model, key string) string {
35		t.Helper()
36		_, value, ok := findHeaderInfo(m, key)
37		if !ok {
38			t.Fatalf("GetHeaderInfo has no %q line", key)
39		}
40		return value
41	}
