43	// stoppingRun returns a snapshot holding one run that was asked to stop while
44	// an item is still running, and the registry that made it so the test can settle
45	// it afterwards.
46	func stoppingRun(t *testing.T) (*jobs.Registry, jobs.JobID, []jobs.Run) {
47		t.Helper()
48		reg := jobs.New()
49		r := jobs.NewRun(jobs.KindSync, command.ViewWorkspaces, testContext, "~/work", "~/work/a", "~/work/b")
50		id := reg.Start(r)
51		if !reg.Advance(id, "~/work/a", jobs.ItemRunning, "") {
52			t.Fatal("the registry refused to run the first target")
