60	func TestFailedIsInTheHeaderAtZero(t *testing.T) {
61		m := withFailures(t, nil)
62		if got := headerValue(t, m, "Failed"); got != "0" {
63			t.Errorf("Failed = %q with no failure, want \"0\"", got)
64		}
