		}
		return out
	}
	want := keys(states["empty"])
	if !slices.Contains(want, "Failed") {
		t.Fatalf("header keys %v lack Failed", want)
	}
	for name, m := range states {
		if got := keys(m); !slices.Equal(got, want) {
			t.Errorf("%s: header keys = %v, want %v", name, got, want)
		}
	}
