func TestTheFooterSaysStoppingWhileACancelledRunHasNotSettled(t *testing.T) {
	_, _, snapshot := stoppingRun(t)
	m := withRuns(t, snapshot...)

	if want := "1 job running · 1 stopping"; m.status().Text != want {
