122			"a run":            withRuns(t, run(1, jobs.KindScan, "~/work", jobs.ItemRunning)),
123			"a failure":        withFailures(t, nil, failureIn(testContext, "~/a", 1)),
124			"a stopping run":   withRuns(t, stopping...),
125			"run and failures": withFailures(t, []jobs.Run{run(1, jobs.KindScan, "~/w", jobs.ItemQueued)}, failureIn(testContext, "~/a", 1), failureIn(testContext, "~/b", 2)),
126		}
127		keys := func(m Model) []string {
